type ListDBFindingsParams struct {
	OrgID  uuid.UUID
	ScanID uuid.UUID
}

func (q *Queries) ListDBFindings(ctx context.Context, arg ListDBFindingsParams) ([]DbFinding, error) {
	rows, err := q.db.Query(ctx, listDBFindings, arg.OrgID, arg.ScanID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DbFinding{}
	for rows.Next() {
		var i DbFinding
		if err := rows.Scan(
			&i.ID,
			&i.OrgID,
			&i.ScanID,
			&i.ConnectionID,
			&i.RuleID,
			&i.Category,
			&i.Severity,
			&i.ObjectType,
			&i.Object,
			&i.Params,
			&i.Details,
			&i.Fingerprint,
			&i.IsNew,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

