const previousDBScanFingerprints = `-- name: PreviousDBScanFingerprints :many
SELECT f.fingerprint FROM db_findings f
WHERE f.scan_id = (
    SELECT s.id FROM db_scans s
    WHERE s.connection_id = $1 AND s.status = 'completed' AND s.id <> $2
    ORDER BY s.finished_at DESC LIMIT 1
)
`

type PreviousDBScanFingerprintsParams struct {
	ConnectionID uuid.UUID
	ID           uuid.UUID
}

func (q *Queries) PreviousDBScanFingerprints(ctx context.Context, arg PreviousDBScanFingerprintsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, previousDBScanFingerprints, arg.ConnectionID, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var fingerprint string
		if err := rows.Scan(&fingerprint); err != nil {
			return nil, err
		}
		items = append(items, fingerprint)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

