const upsertDBProfile = `-- name: UpsertDBProfile :exec
INSERT INTO db_profiles (org_id, profile, updated_by, updated_at) VALUES ($1, $2, $3, now())
ON CONFLICT (org_id) DO UPDATE SET profile = EXCLUDED.profile, updated_by = EXCLUDED.updated_by, updated_at = now()
`

type UpsertDBProfileParams struct {
	OrgID     uuid.UUID
	Profile   json.RawMessage
	UpdatedBy *uuid.UUID
}

func (q *Queries) UpsertDBProfile(ctx context.Context, arg UpsertDBProfileParams) error {
	_, err := q.db.Exec(ctx, upsertDBProfile, arg.OrgID, arg.Profile, arg.UpdatedBy)
	return err
}

